unsigned long djb2(const char *s) {
  unsigned long h = 5381; int c;
  while ((c = *s++)) h = h * 33 + c;
  return h;
}
size_t idx = djb2(key) % cap;

typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
Entry *table[CAP];
void put(const char *k, int v) {
  size_t i = djb2(k) % CAP;
  for (Entry *e = table[i]; e; e = e->next) if (!strcmp(e->key, k)) { e->val = v; return; }
  Entry *n = malloc(sizeof *n); n->key = strdup(k); n->val = v; n->next = table[i]; table[i] = n;
}
